@Component("loanPayment-handler")
@ProcessingGroup("loanPayment-processing-group")
public class LoanPaymentEventHandler {
	
	// core constructor
	LoanPaymentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLoanPaymentEvent
     */
    @EventHandler
    public void handle( CreateLoanPaymentEvent event) {
        entityManager.persist(new LoanPayment(event.getLoanPaymentId(), event.getPaymentReference(), event.getAmount(), event.getPaymentDate(), event.getLoanAccount(), event.getTransaction(), event.getMethod(), event.getStatus()));
    }

    /*
     * @param	event UpdateLoanPaymentEvent
     */
    @EventHandler
    public LoanPayment handle( UpdateLoanPaymentEvent event) {
    	entityManager.merge(new LoanPayment(event.getLoanPaymentId(), event.getPaymentReference(), event.getAmount(), event.getPaymentDate(), event.getLoanAccount(), event.getTransaction(), event.getMethod(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteLoanPaymentEvent
     */
    @EventHandler
    public void on( DeleteLoanPaymentEvent event) {
    	LoanPayment entity = new LoanPayment();
   
    	// ------------------------------------------
    	// apply the LoanPaymentId
    	// ------------------------------------------
    	entity.setLoanPaymentId( event.getLoanPaymentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LoanPaymentRepository loanPaymentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LoanPaymentEventHandler.class.getName());

}
